var numFactoredBinaryTrees = function(arr) {
    const MOD = 1000000007n;
    arr.sort((a, b) => a - b);

    const dp = new Map();
    for (const num of arr) {
        dp.set(num, 1n);
    }

    for (let i = 0; i < arr.length; i++) {
        const val = arr[i];
        for (let j = 0; j < i; j++) {
            const left = arr[j];
