                if (dp.has(right)) {
                    const ways = (dp.get(left) * dp.get(right)) % MOD;
                    dp.set(val, (dp.get(val) + ways) % MOD);
                }
            }
        }
    }

    let total = 0n;
    for (const count of dp.values()) {
        total = (total + count) % MOD;
    }

    return Number(total);
};
