```javascript
/**
 * @param {number} m
 * @param {number} k
 */
var MKAverage = function(m, k) {
    this.m = m;
    this.k = k;
    this.buf = new Int32Array(m);
    this.pos = 0;
    this.total = 0;
    this.bitCount = new Int32Array(100001);
    this.bitSum = new Float64Array(100001);
};

/** 
 * @param {number} num
 * @return {void}
 */
MKAverage.prototype.addElement = function(num) {
    if (this.total >= this.m) {
        const old = this.buf[this.pos];
        for (let i = old; i <= 100000; i += i & -i) {
            this.bitCount[i]--;
            this.bitSum[i] -= old;
        }
    }
    this.buf[this.pos] = num;
    this.pos = (this.pos + 1) % this.m;
    this.total++;

    for (let i = num; i <= 100000; i += i & -i) {
        this.bitCount[i]++;
        this.bitSum[i] += num;
    }
};

/**
 * @param {number} C
 * @return {number}
 */
MKAverage.prototype.getSumOfFirst = function(C) {
    if (C === 0) return 0;
    let idx = 0;
    let currentCount = 0;
    let currentSum = 0;
    for (let step = 1 << 16; step > 0; step >>= 1) {
        const next = idx + step;
        if (next <= 100000 && currentCount + this.bitCount[next] < C) {
            idx = next;
            currentCount += this.bitCount[idx];
            currentSum += this.bitSum[idx];
        }
    }
    const rem = C - currentCount;
    currentSum += rem * (idx + 1);
    return currentSum;
};

/**
 * @return {number}
 */
MKAverage.prototype.calculateMKAverage = function() {
    if (this.total < this.m) return -1;
    const sumK = this.getSumOfFirst(this.k);
    const sumMK = this.getSumOfFirst(this.m - this.k);
    const midSum = sumMK - sumK;
    return Math.floor(midSum / (this.m - 2 * this.k));
};
```

