var canCross = function(stones) {
    const n = stones.length;
    if (stones[1] !== 1) return false;

    const stoneMap = new Map();
    for (let i = 0; i < n; i++) {
        stoneMap.set(stones[i], i);
    }

    const memo = new Set();

    function dfs(i, k) {
        if (i === n - 1) return true;

        const key = (i << 12) | k;
        if (memo.has(key)) return false;

        for (let jump = k - 1; jump <= k + 1; jump++) {
