    const m = grid.length;
    const n = grid[0].length;

    const rowSum = Array.from({ length: m }, () => new Int32Array(n + 1));
    const colSum = Array.from({ length: m + 1 }, () => new Int32Array(n));

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            rowSum[r][c + 1] = rowSum[r][c] + grid[r][c];
            colSum[r + 1][c] = colSum[r][c] + grid[r][c];
