                let isMagic = true;

                // Check remaining rows
                for (let i = 1; i < k; i++) {
                    if (rowSum[r + i][c + k] - rowSum[r + i][c] !== target) {
                        isMagic = false;
                        break;
                    }
                }
                if (!isMagic) continue;

                // Check columns
                for (let j = 0; j < k; j++) {
                    if (colSum[r + k][c + j] - colSum[r][c + j] !== target) {
                        isMagic = false;
                        break;
