var maximumBeauty = function(flowers, newFlowers, target, full, partial) {
    const n = flowers.length;
    flowers.sort((a, b) => a - b);

    for (let i = 0; i < n; i++) {
        if (flowers[i] > target) {
            flowers[i] = target;
        }
    }

    const pref = new BigInt64Array(n + 1);
    for (let i = 0; i < n; i++) {
        pref[i + 1] = pref[i] + BigInt(flowers[i]);
    }

    const bTarget = BigInt(target);
    const bFull = BigInt(full);
    const bPartial = BigInt(partial);
    const bNewFlowers = BigInt(newFlowers);

    let maxBeauty = 0n;

    // Check case where all gardens are complete
    const totalCostAllComplete = BigInt(n) * bTarget - pref[n];
    if (totalCostAllComplete <= bNewFlowers) {
        maxBeauty = BigInt(n) * bFull;
    }

    let p = 0; // pointer for incomplete gardens
    // c is the number of complete gardens (from 0 to n - 1)
    for (let c = 0; c < n; c++) {
        const costSuffix = BigInt(c) * bTarget - (pref[n] - pref[n - c]);
        if (costSuffix > bNewFlowers) {
            break;
        }

        const rem = bNewFlowers - costSuffix;
        const incompleteCount = n - c;

        // Binary search for the maximum minimum value x in [flowers[0], target - 1]
        let low = flowers[0];
        let high = target - 1;
        let bestMin = flowers[0];

        while (low <= high) {
            const mid = (low + high) >> 1;
            const bMid = BigInt(mid);

            // Find number of gardens in incompleteCount with flowers[i] < mid
            let l = 0, r = incompleteCount;
            while (l < r) {
                const m = (l + r) >> 1;
                if (flowers[m] <= mid) {
                    l = m + 1;
                } else {
                    r = m;
                }
            }
            const k = l;
            const cost = BigInt(k) * bMid - pref[k];

            if (cost <= rem) {
                bestMin = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        const currentBeauty = BigInt(c) * bFull + BigInt(bestMin) * bPartial;
        if (currentBeauty > maxBeauty) {
            maxBeauty = currentBeauty;
        }
    }

    return Number(maxBeauty);
};
