/**
 * @param {number} maxTime
 * @param {number[][]} edges
 * @param {number[]} passingFees
 * @return {number}
 */
var minCost = function(maxTime, edges, passingFees) {
    const n = passingFees.length;
    const INF = 1e9;

    // dp[t][i] represents the minimum cost to reach city i at time t
    const dp = Array.from({ length: maxTime + 1 }, () => new Int32Array(n).fill(INF));
    dp[0][0] = passingFees[0];

    for (let t = 1; t <= maxTime; t++) {
        for (let i = 0; i < edges.length; i++) {
            const [u, v, time] = edges[i];
            if (t >= time) {
                if (dp[t - time][u] !== INF) {
                    dp[t][v] = Math.min(dp[t][v], dp[t - time][u] + passingFees[v]);
                }
                if (dp[t - time][v] !== INF) {
                    dp[t][u] = Math.min(dp[t][u], dp[t - time][v] + passingFees[u]);
                }
            }
        }
    }

    let ans = INF;
    for (let t = 0; t <= maxTime; t++) {
        ans = Math.min(ans, dp[t][n - 1]);
    }

    return ans === INF ? -1 : ans;
};
