```javascript
/**
 * @param {string} binary
 * @return {string}
 */
var maximumBinaryString = function(binary) {
    const firstZero = binary.indexOf('0');
    if (firstZero === -1) {
        return binary;
    }

    let zerosCount = 0;
    for (let i = firstZero; i < binary.length; i++) {
        if (binary[i] === '0') {
            zerosCount++;
        }
    }

    if (zerosCount <= 1) {
        return binary;
    }

    const zeroIndex = firstZero + zerosCount - 1;
    const res = new Array(binary.length).fill('1');
    res[zeroIndex] = '0';

    return res.join('');
};
