/**
 * @param {number[][]} grid
 * @return {number}
 */
var minDays = function(grid) {
    const m = grid.length;
    const n = grid[0].length;

    function countIslands() {
        const visited = Array.from({ length: m }, () => new Uint8Array(n));
        let count = 0;

        for (let i = 0; i < m; i++) {
            for (let j = 0; j < n; j++) {
                if (grid[i][j] === 1 && !visited[i][j]) {
                    count++;
                    if (count > 1) return count;

                    const queue = [[i, j]];
                    visited[i][j] = 1;
                    let head = 0;

                    while (head < queue.length) {
                        const [r, c] = queue[head++];
                        const dirs = [-1, 0, 1, 0, -1];
                        for (let d = 0; d < 4; d++) {
                            const nr = r + dirs[d];
                            const nc = c + dirs[d + 1];
                            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] === 1 && !visited[nr][nc]) {
                                visited[nr][nc] = 1;
                                queue.push([nr, nc]);
                            }
                        }
                    }
                }
            }
        }
        return count;
    }

    if (countIslands() !== 1) {
        return 0;
    }

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 1) {
                grid[i][j] = 0;
                if (countIslands() !== 1) {
                    return 1;
                }
                grid[i][j] = 1;
            }
        }
    }

    return 2;
};
