/**
 * @param {number[]} bloomDay
 * @param {number} m
 * @param {number} k
 * @return {number}
 */
var minDays = function(bloomDay, m, k) {
    if (m * k > bloomDay.length) {
        return -1;
    }

    let low = 1;
    let high = 0;
    for (let i = 0; i < bloomDay.length; i++) {
        if (bloomDay[i] > high) {
            high = bloomDay[i];
        }
    }

    const canMake = (days) => {
        let bouquets = 0;
        let flowers = 0;
        for (let i = 0; i < bloomDay.length; i++) {
            if (bloomDay[i] <= days) {
                flowers++;
                if (flowers === k) {
                    bouquets++;
                    flowers = 0;
                }
            } else {
                flowers = 0;
            }
        }
        return bouquets >= m;
    };

    let ans = -1;
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        if (canMake(mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    return ans;
};
