/**
 * @param {number[]} slices
 * @return {number}
 */
var maxSizeSlices = function(slices) {
    const n = Math.floor(slices.length / 3);

    const maxLinear = (arr, k) => {
        const m = arr.length;
        const dp = Array.from({ length: m + 1 }, () => new Int32Array(k + 1).fill(-1e9));
        for (let i = 0; i <= m; i++) {
            dp[i][0] = 0;
        }

        for (let i = 1; i <= m; i++) {
            for (let j = 1; j <= k; j++) {
                const notPick = dp[i - 1][j];
                const prev = i >= 2 ? dp[i - 2][j - 1] : (j === 1 ? 0 : -1e9);
                const pick = prev + arr[i - 1];
                dp[i][j] = Math.max(notPick, pick);
            }
        }

        return dp[m][k];
    };

    const case1 = maxLinear(slices.slice(1), n);
    const case2 = maxLinear(slices.slice(0, slices.length - 1), n);

    return Math.max(case1, case2);
};
