/**
 * @param {number} n
 * @param {number[][]} restrictions
 * @param {number[][]} requests
 * @return {boolean[]}
 */
var friendRequests = function(n, restrictions, requests) {
    const parent = new Int32Array(n);
    for (let i = 0; i < n; i++) {
        parent[i] = i;
    }

    function find(i) {
        let root = i;
        while (root !== parent[root]) {
            root = parent[root];
        }
        let curr = i;
        while (curr !== root) {
            let nxt = parent[curr];
            parent[curr] = root;
            curr = nxt;
        }
        return root;
    }

    const result = new Array(requests.length);

    for (let i = 0; i < requests.length; i++) {
        const u = requests[i][0];
        const v = requests[i][1];

        const rootU = find(u);
        const rootV = find(v);

        if (rootU === rootV) {
            result[i] = true;
            continue;
        }

        let canBeFriends = true;
        for (let j = 0; j < restrictions.length; j++) {
            const rootX = find(restrictions[j][0]);
            const rootY = find(restrictions[j][1]);

            if (
                (rootX === rootU && rootY === rootV) ||
                (rootX === rootV && rootY === rootU)
            ) {
                canBeFriends = false;
                break;
            }
        }

        if (canBeFriends) {
            parent[rootU] = rootV;
            result[i] = true;
        } else {
            result[i] = false;
        }
    }

    return result;
};
