/**
 * @param {number[]} tasks
 * @param {number} sessionTime
 * @return {number}
 */
var minSessions = function(tasks, sessionTime) {
    const n = tasks.length;
    const totalMasks = 1 << n;
    const dp = new Int32Array(totalMasks).fill(1e9);

    // dp[mask] = (sessions << 5) | time
    dp[0] = (1 << 5) | 0;

    for (let mask = 0; mask < totalMasks; mask++) {
        const curr = dp[mask];
        const sess = curr >> 5;
        const time = curr & 31;

        for (let i = 0; i < n; i++) {
            if ((mask & (1 << i)) === 0) {
                const nextMask = mask | (1 << i);
                let cand;
                if (time + tasks[i] <= sessionTime) {
                    cand = (sess << 5) | (time + tasks[i]);
                } else {
                    cand = ((sess + 1) << 5) | tasks[i];
                }
                if (cand < dp[nextMask]) {
                    dp[nextMask] = cand;
                }
            }
        }
    }

    return dp[totalMasks - 1] >> 5;
};
