var removeInvalidParentheses = function(s) {
    let leftRem = 0, rightRem = 0;
    for (let i = 0; i < s.length; i++) {
        if (s[i] === '(') {
            leftRem++;
        } else if (s[i] === ')') {
            if (leftRem > 0) {
                leftRem--;
            } else {
                rightRem++;
            }
        }
    }

    const result = new Set();
    const path = [];

    function dfs(index, leftRem, rightRem, openCount) {
        if (index === s.length) {
            if (leftRem === 0 && rightRem === 0 && openCount === 0) {
                result.add(path.join(''));
            }
            return;
        }

        const ch = s[index];

        // Option 1: Remove the current character (if it's a parenthesis and we have removals left)
        if (ch === '(' && leftRem > 0) {
            dfs(index + 1, leftRem - 1, rightRem, openCount);
        } else if (ch === ')' && rightRem > 0) {
            dfs(index + 1, leftRem, rightRem - 1, openCount);
        }

        // Option 2: Keep the current character
        path.push(ch);
        if (ch !== '(' && ch !== ')') {
            dfs(index + 1, leftRem, rightRem, openCount);
        } else if (ch === '(') {
            dfs(index + 1, leftRem, rightRem, openCount + 1);
        } else if (ch === ')' && openCount > 0) {
            dfs(index + 1, leftRem, rightRem, openCount - 1);
        }
        path.pop();
    }

    dfs(0, leftRem, rightRem, 0);
    return Array.from(result);
};
