/**
 * @param {string} s1
 * @param {string} s2
 * @return {boolean}
 */
var isScramble = function(s1, s2) {
    const n = s1.length;
    if (n !== s2.length) return false;
    if (s1 === s2) return true;

    // memo[len][i][j] : -1 unvisited, 0 false, 1 true
    const memo = Array.from({ length: n + 1 }, () =>
        Array.from({ length: n }, () => new Int8Array(n).fill(-1))
    );

    function solve(i, j, len) {
        if (memo[len][i][j] !== -1) {
            return memo[len][i][j] === 1;
        }

        let same = true;
        for (let k = 0; k < len; k++) {
            if (s1.charCodeAt(i + k) !== s2.charCodeAt(j + k)) {
                same = false;
                break;
            }
        }
        if (same) {
            memo[len][i][j] = 1;
            return true;
        }

        const count = new Int32Array(26);
        for (let k = 0; k < len; k++) {
            count[s1.charCodeAt(i + k) - 97]++;
            count[s2.charCodeAt(j + k) - 97]--;
        }
        for (let k = 0; k < 26; k++) {
            if (count[k] !== 0) {
                memo[len][i][j] = 0;
                return false;
            }
        }

        for (let k = 1; k < len; k++) {
            // Case 1: without swap
            if (solve(i, j, k) && solve(i + k, j + k, len - k)) {
                memo[len][i][j] = 1;
                return true;
            }
            // Case 2: with swap
            if (solve(i, j + len - k, k) && solve(i + k, j, len - k)) {
                memo[len][i][j] = 1;
                return true;
            }
        }

        memo[len][i][j] = 0;
        return false;
    }

    return solve(0, 0, n);
};
