/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number[]}
 */
var medianSlidingWindow = function(nums, k) {
    const n = nums.length;
    const unique = Array.from(new Set(nums)).sort((a, b) => a - b);
    const M = unique.length;

    const valToIdx = new Map();
    for (let i = 0; i < M; i++) {
        valToIdx.set(unique[i], i + 1);
    }

    const tree = new Int32Array(M + 1);

    function add(i, delta) {
        for (; i <= M; i += i & -i) {
            tree[i] += delta;
        }
    }

    let maxPow = 1;
    while (maxPow <= M) {
        maxPow <<= 1;
    }

    function findKth(rank) {
        let idx = 0;
        for (let step = maxPow; step > 0; step >>= 1) {
            if (idx + step <= M && tree[idx + step] < rank) {
                idx += step;
                rank -= tree[idx];
            }
        }
        return unique[idx];
    }

    for (let i = 0; i < k; i++) {
        add(valToIdx.get(nums[i]), 1);
    }

    const result = new Array(n - k + 1);
    const isOdd = (k % 2 === 1);
    const mid1 = isOdd ? Math.floor((k + 1) / 2) : k / 2;
    const mid2 = mid1 + 1;

    for (let i = 0; i <= n - k; i++) {
        if (isOdd) {
            result[i] = findKth(mid1);
        } else {
            result[i] = (findKth(mid1) + findKth(mid2)) / 2;
        }

        if (i < n - k) {
            add(valToIdx.get(nums[i]), -1);
            add(valToIdx.get(nums[i + k]), 1);
        }
    }

    return result;
};
