var StreamChecker = function(words) {
    this.trie = {};
    this.stream = [];
    this.maxLen = 0;

    for (let i = 0; i < words.length; i++) {
        const word = words[i];
        if (word.length > this.maxLen) {
            this.maxLen = word.length;
        }
        let curr = this.trie;
        for (let j = word.length - 1; j >= 0; j--) {
