};

/** 
 * @param {character} letter
 * @return {boolean}
 */
StreamChecker.prototype.query = function(letter) {
    this.stream.push(letter);
    let curr = this.trie;
    const minIdx = Math.max(0, this.stream.length - this.maxLen);

    for (let i = this.stream.length - 1; i >= minIdx; i--) {
        const ch = this.stream[i];
        if (!curr[ch]) {
            return false;
        }
        curr = curr[ch];
        if (curr.isEnd) {
            return true;
        }
    }

    return false;
};

