/**
 * @param {number[]} nums
 * @param {number[][]} edges
 * @return {number[]}
 */
var getCoprimes = function(nums, edges) {
    const n = nums.length;

    const gcd = (a, b) => {
        while (b !== 0) {
            const t = b;
            b = a % b;
            a = t;
        }
        return a;
    };

    const coprimes = Array.from({ length: 51 }, () => []);
    for (let i = 1; i <= 50; i++) {
        for (let j = 1; j <= 50; j++) {
            if (gcd(i, j) === 1) {
                coprimes[i].push(j);
            }
        }
    }

    const adj = Array.from({ length: n }, () => []);
    for (let i = 0; i < edges.length; i++) {
        const u = edges[i][0];
        const v = edges[i][1];
        adj[u].push(v);
        adj[v].push(u);
    }

    const ans = new Int32Array(n).fill(-1);

    const valStackNode = Array.from({ length: 51 }, () => []);
    const valStackDepth = Array.from({ length: 51 }, () => []);

    const stackNode = new Int32Array(n);
    const stackParent = new Int32Array(n);
    const stackEdgeIdx = new Int32Array(n);
    const stackDepth = new Int32Array(n);

    stackNode[0] = 0;
    stackParent[0] = -1;
    stackEdgeIdx[0] = 0;
    stackDepth[0] = 0;
    let stackPtr = 1;

    while (stackPtr > 0) {
        const top = stackPtr - 1;
        const u = stackNode[top];
        const p = stackParent[top];
        const d = stackDepth[top];
        const neighbors = adj[u];

        if (stackEdgeIdx[top] === 0) {
            let bestNode = -1;
            let maxDepth = -1;
            const coprimeVals = coprimes[nums[u]];
            for (let i = 0; i < coprimeVals.length; i++) {
                const val = coprimeVals[i];
                const len = valStackNode[val].length;
                if (len > 0) {
                    const depth = valStackDepth[val][len - 1];
                    if (depth > maxDepth) {
                        maxDepth = depth;
                        bestNode = valStackNode[val][len - 1];
                    }
                }
            }
            ans[u] = bestNode;

            valStackNode[nums[u]].push(u);
            valStackDepth[nums[u]].push(d);
        }

        if (stackEdgeIdx[top] < neighbors.length) {
            const v = neighbors[stackEdgeIdx[top]++];
            if (v !== p) {
                stackNode[stackPtr] = v;
                stackParent[stackPtr] = u;
                stackEdgeIdx[stackPtr] = 0;
                stackDepth[stackPtr] = d + 1;
                stackPtr++;
            }
        } else {
            valStackNode[nums[u]].pop();
            valStackDepth[nums[u]].pop();
            stackPtr--;
        }
    }

    return Array.from(ans);
};
