/**
 * @param {number[][]} mat
 * @param {number} k
 * @return {number[]}
 */
var kWeakestRows = function(mat, k) {
    const rowStrengths = mat.map((row, index) => {
        let count = 0;
        for (const val of row) {
            if (val === 1) {
                count++;
            } else {
                break;
            }
        }
        return [count, index];
    });

    rowStrengths.sort((a, b) => {
        if (a[0] !== b[0]) {
            return a[0] - b[0];
        }
        return a[1] - b[1];
    });

    return rowStrengths.slice(0, k).map(item => item[1]);
};
