/**
 * @param {number} rows
 * @param {number} cols
 * @param {number} rStart
 * @param {number} cStart
 * @return {number[][]}
 */
var spiralMatrixIII = function(rows, cols, rStart, cStart) {
    const total = rows * cols;
    const res = [[rStart, cStart]];

    const dirs = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    let r = rStart;
    let c = cStart;
    let step = 1;
    let dirIdx = 0;

    while (res.length < total) {
        for (let i = 0; i < 2; i++) {
            const [dr, dc] = dirs[dirIdx];
            for (let s = 0; s < step; s++) {
                r += dr;
                c += dc;
                if (r >= 0 && r < rows && c >= 0 && c < cols) {
                    res.push([r, c]);
                }
            }
            dirIdx = (dirIdx + 1) % 4;
        }
        step++;
    }

    return res;
};
