/**
 * @param {string} s1
 * @param {string} s2
 * @return {string[]}
 */
var uncommonFromSentences = function(s1, s2) {
    const counts = new Map();
    const words = (s1 + " " + s2).split(" ");

    for (const word of words) {
        counts.set(word, (counts.get(word) || 0) + 1);
    }

    const result = [];
    for (const [word, count] of counts) {
        if (count === 1) {
            result.push(word);
        }
    }

    return result;
};
