/**
 * @param {number} a
 * @param {number} b
 * @return {string}
 */
var strWithout3a3b = function(a, b) {
    const res = [];
    while (a > 0 || b > 0) {
        const len = res.length;
        let writeA = false;
        if (len >= 2 && res[len - 1] === 'a' && res[len - 2] === 'a') {
            writeA = false;
        } else if (len >= 2 && res[len - 1] === 'b' && res[len - 2] === 'b') {
            writeA = true;
        } else {
            writeA = a >= b;
        }

        if (writeA) {
            res.push('a');
            a--;
        } else {
            res.push('b');
            b--;
        }
    }
    return res.join('');
};
