/**
 * @param {string} s
 * @param {string} p
 * @return {boolean}
 */
var isMatch = function(s, p) {
    let sIdx = 0, pIdx = 0;
    let starIdx = -1, matchIdx = 0;

    while (sIdx < s.length) {
        if (pIdx < p.length && (p[pIdx] === '?' || p[pIdx] === s[sIdx])) {
            sIdx++;
            pIdx++;
        } else if (pIdx < p.length && p[pIdx] === '*') {
            starIdx = pIdx;
            matchIdx = sIdx;
            pIdx++;
        } else if (starIdx !== -1) {
            pIdx = starIdx + 1;
            matchIdx++;
            sIdx = matchIdx;
        } else {
            return false;
        }
    }

    while (pIdx < p.length && p[pIdx] === '*') {
        pIdx++;
    }

    return pIdx === p.length;
};
